import numpy as np, pandas as pd

def stats(rets):
    nav = np.concatenate([[1.0], np.cumprod(1+np.array(rets))])
    peak = np.maximum.accumulate(nav)
    dd = nav/peak - 1
    return nav, dd.min(), np.std(rets, ddof=1)

for r in ([ -0.20, 0.20], [0.20, -0.20], [-0.10, 0.20], [0.20, -0.10], [-0.10, 0.50], [0.50, -0.10]):
    nav, mdd, sd = stats(r)
    print(r, "NAV path:", np.round(nav,4), "MDD:", round(mdd,4), "vol(样本std):", round(sd,4))

